{
  "name": "tinySA 频谱分析仪",
  "name_en": "tinySA spectrum analyzer",
  "manufacturer": "",
  "description": "用于射频信号观察与基础频谱分析的 tinySA 频谱分析仪，可通过 SCPI/USB 发送命令、执行原始频段扫描、抓取屏幕截图、自检，并调用多种射频测量功能。",
  "description_en": "A tinySA spectrum analyzer for RF signal observation and basic spectrum analysis. It can be controlled over SCPI/USB to send commands, perform raw frequency scans, capture screenshots, run self-tests, and invoke multiple RF measurement functions.",
  "tag_hints": [
    "RF spectrum analysis",
    "SCPI over USB",
    "raw frequency scan",
    "phase noise measurement",
    "harmonic measurement",
    "channel power",
    "modulation analysis",
    "OIP3"
  ],
  "actions": [
    {
      "action_name": "auto-convert_scpi_to_usb",
      "description": "将 SCPI 命令转换为设备可用的 USB 命令格式",
      "description_en": "Convert an SCPI command into the USB command format used by the device"
    },
    {
      "action_name": "auto-send",
      "description": "向设备发送命令",
      "description_en": "Send a command to the device"
    },
    {
      "action_name": "auto-take_screenshot",
      "description": "抓取设备屏幕截图",
      "description_en": "Capture a screenshot from the device display"
    },
    {
      "action_name": "auto-scan_raw",
      "description": "在指定频率范围内执行原始扫描",
      "description_en": "Perform a raw scan over a specified frequency range"
    },
    {
      "action_name": "auto-selftest",
      "description": "运行设备自检",
      "description_en": "Run the device self-test"
    },
    {
      "action_name": "auto-MEASure_OFF",
      "description": "关闭测量功能",
      "description_en": "Turn off the measurement function"
    },
    {
      "action_name": "auto-MEASure_HARMonic",
      "description": "执行谐波测量命令",
      "description_en": "Execute the harmonic measurement command"
    },
    {
      "action_name": "auto-MEASure_OIP3",
      "description": "执行三阶输出截点（OIP3）测量命令",
      "description_en": "Execute the output third-order intercept (OIP3) measurement command"
    },
    {
      "action_name": "auto-MEASure_PhaseNOISe",
      "description": "执行相位噪声测量命令",
      "description_en": "Execute the phase noise measurement command"
    },
    {
      "action_name": "auto-MEASure_SNR",
      "description": "执行信噪比测量命令",
      "description_en": "Execute the signal-to-noise ratio measurement command"
    },
    {
      "action_name": "auto-MEASure_3DB",
      "description": "执行 3 dB 测量命令",
      "description_en": "Execute the 3 dB measurement command"
    },
    {
      "action_name": "auto-MEASure_AM",
      "description": "执行 AM 测量命令",
      "description_en": "Execute the AM measurement command"
    },
    {
      "action_name": "auto-MEASure_FM",
      "description": "执行 FM 测量命令",
      "description_en": "Execute the FM measurement command"
    },
    {
      "action_name": "auto-MEASure_THD",
      "description": "执行总谐波失真测量命令",
      "description_en": "Execute the total harmonic distortion measurement command"
    },
    {
      "action_name": "auto-MEASure_CHPOW",
      "description": "执行信道功率测量命令",
      "description_en": "Execute the channel power measurement command"
    },
    {
      "action_name": "auto-MEASure_LINEar",
      "description": "执行线性度测量命令",
      "description_en": "Execute the linearity measurement command"
    },
    {
      "action_name": "auto-get_device",
      "description": "获取已连接设备对象",
      "description_en": "get connected device object"
    }
  ]
}

